Here's a sample End User API for 3D Camera Animation in TypeScript:

```typescript
import { Camera, Scene } from 'three';

class CameraAnimationAPI {
  private scene: Scene;
  private camera: Camera;

  constructor(scene: Scene, camera: Camera) {
    this.scene = scene;
    this.camera = camera;
  }

  public animateCamera(animation: any): void {
    // Implement the animation logic here
    // You can use Three.js animations or create your own custom animation
    // For example:
    const animationDuration = animation.duration;
    const animationIterations = animation.iterations;
    const animationEasing = animation.easing;

    const animationCallback = (time: number) => {
      const currentTime = time / animationDuration;
      const interpolation = animationEasing(currentTime);

      const newCameraPosition = animation.position(interpolation);
      const newCameraRotation = animation.rotation(interpolation);

      this.camera.position.set(newCameraPosition.x, newCameraPosition.y, newCameraPosition.z);
      this.camera.rotation.set(newCameraRotation.x, newCameraRotation.y, newCameraRotation.z);
    };

    requestAnimationFrame(animationCallback);
  }
}

const scene = new Scene();
const camera = new Camera();

const cameraAnimationAPI = new CameraAnimationAPI(scene, camera);

// Example usage:
const animation = {
  duration: 1000,
  iterations: 1,
  easing: (t) => t,
  position: (t) => [t * 100, t * 50, t * 20],
  rotation: (t) => [t * Math.PI / 2, t * Math.PI / 2, t * Math.PI / 2]
};

cameraAnimationAPI.animateCamera(animation);
```

