```matlab
% Input parameters
a = 6378137; % Earth's semi-major axis in meters
b = 6356752.3142; % Earth's semi-minor axis in meters
lat1 = deg2rad(37.7749); % latitude of point 1 in degrees
lon1 = deg2rad(-122.4194); % longitude of point 1 in degrees
lat2 = deg2rad(51.5074); % latitude of point 2 in degrees
lon2 = deg2rad(-0.1278); % longitude of point 2 in degrees

% Calculate the flattening and eccentricity squared
f = (a-b)/a;
e2 = 2*f - f^2;

% Calculate the radii of curvature in the prime vertical at both points
N1 = a/sqrt(1-e2*sin(lat1)^2);
N2 = a/sqrt(1-e2*sin(lat2)^2);

% Convert latitudes and longitudes to Cartesian coordinates
x1 = (N1+h1)*cos(lat1)*cos(lon1);
y1 = (N1+h1)*cos(lat1)*sin(lon1);
z1 = ((1-e2)*N1+h1)*sin(lat1);
x2 = (N2+h2)*cos(lat2)*cos(lon2);
y2 = (N2+h2)*cos(lat2)*sin(lon2);
z2 = ((1-e2)*N2+h2)*sin(lat2);

% Calculate the distance between the two points
d = sqrt((x1-x2)^2 + (y1-y2)^2 + (z1-z2)^2);

% Display the result
fprintf('The distance between San Francisco and London is %.2f meters.\n', d);
```

