Here's a simple C function that converts an array of command-line arguments (`argv`) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *argv_to_cstring(int argc, char **argv) {
    size_t len = 0;
    for (int i = 0; i < argc; i++) {
        len += strlen(argv[i]) + 1; // Add 1 for the null terminator
    }

    char *cstring = malloc(len);
    if (cstring == NULL) {
        fprintf(stderr, "Error allocating memory\n");
        return NULL;
    }

    char *ptr = cstring;
    for (int i = 0; i < argc; i++) {
        strcpy(ptr, argv[i]);
        ptr += strlen(argv[i]) + 1; // Move to the next position
    }
    *ptr = '\0'; // Add the null terminator

    return cstring;
}

int main(int argc, char **argv) {
    char *cstring = argv_to_cstring(argc, argv);
    if (cstring != NULL) {
        printf("C string: %s\n", cstring);
        free(cstring);
    }

    return 0;
}
```

This function takes two arguments: `argc` (the number of command-line arguments) and `argv` (an array of pointers to the command-line arguments). It allocates memory for a null-terminated string, copies the command-line arguments into the string, and returns it. Make sure to call `free()` on the returned string when you're done with it to avoid memory leaks.

