To create a simple toast notification using React context, follow these steps:

1. Create a `ToastContext` component:

```javascript
import { createContext, useReducer } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toasts, dispatch] = useReducer(toastReducer, []);

  function showToast(message) {
    dispatch({ type: 'SHOW_TOAST', message });
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

function toastReducer(state, action) {
  switch (action.type) {
    case 'SHOW_TOAST':
      return [...state, action.message];
    default:
      return state;
  }
}

export { ToastContext, ToastProvider };
```

2. Use the `ToastContext` in your components:

```javascript
import React from 'react';
import { useContext } from 'react';
import ToastContext from './ToastContext';

function MyComponent() {
  const { showToast } = useContext(ToastContext);

  function handleClick() {
    showToast('This is a toast notification!');
  }

  return (
    <div>
      <button onClick={handleClick}>Show Toast</button>
    </div>
  );
}

export default MyComponent;
```

3. Render the `ToastProvider` in your app:

```javascript
import React from 'react';
import ToastContext from './ToastContext';
import MyComponent from './MyComponent';

function App() {
  return (
    <ToastContext.Provider>
      <MyComponent />
    </ToastContext.Provider>
  );
}

export default App;
```

Now you have a simple toast notification system using React context. You can use the `showToast` function provided by the `ToastContext` to display toast notifications in your components.

