```sql
-- Function to validate temperature input
CREATE FUNCTION validate_temperature(temp DECIMAL) RETURNS BOOLEAN AS $$
BEGIN
    IF temp < -273.15 OR temp > 1000 THEN
        RETURN FALSE;
    END IF;
    RETURN TRUE;
END;
$$ LANGUAGE plpgsql;

-- Function to convert Celsius to Fahrenheit
CREATE FUNCTION celsius_to_fahrenheit(celsius DECIMAL) RETURNS DECIMAL AS $$
BEGIN
    DECLARE fahrenheit DECIMAL;
    fahrenheit := (celsius * 9 / 5) + 32;
    RETURN fahrenheit;
END;
$$ LANGUAGE plpgsql;

